#!/usr/bin/env python3
import os, sys, re, math, struct
from dataclasses import dataclass, field

VERSION = "0.5.8"

# ---------- basic source / tokens ----------
KEYWORDS = {
    'let':'TOKEN_LET','in':'TOKEN_IN','rec':'TOKEN_REC','inherit':'TOKEN_INHERIT',
    'if':'TOKEN_IF','then':'TOKEN_THEN','else':'TOKEN_ELSE','assert':'TOKEN_ASSERT',
    'with':'TOKEN_WITH','or':'TOKEN_OR',
}
PRIMARY_WANTED = "[TOKEN_L_PAREN, TOKEN_REC, TOKEN_L_BRACE, TOKEN_L_BRACK, TOKEN_STRING_START, TOKEN_IDENT]"

def byte_offsets(s):
    offs=[0]*(len(s)+1)
    total=0
    for i,ch in enumerate(s):
        offs[i]=total
        total += len(ch.encode('utf-8', 'surrogatepass'))
    offs[len(s)]=total
    return offs

@dataclass
class Token:
    kind: str
    start: int
    end: int
    text: str = ""
    bstart: int = 0
    bend: int = 0

@dataclass
class Node:
    kind: str
    children: list = field(default_factory=list)  # Node or Token (non-trivia only normally)
    # explicit range if no children / errors
    _start: int = None
    _end: int = None
    parent: object = None
    # extra attributes used by some nodes
    extra: dict = field(default_factory=dict)
    def __post_init__(self):
        for c in self.children:
            if isinstance(c, Node):
                c.parent=self
    @property
    def start(self):
        if self._start is not None:
            return self._start
        if self.children:
            c=self.children[0]
            return c.start
        return 0
    @property
    def end(self):
        if self._end is not None:
            return self._end
        if self.children:
            c=self.children[-1]
            return c.end
        return self.start
    def text_of(self, src):
        return src[self.start:self.end]
    def child_nodes(self):
        return [c for c in self.children if isinstance(c,Node)]
    def child_tokens(self):
        return [c for c in self.children if isinstance(c,Token)]
    def first_child_node(self):
        for c in self.children:
            if isinstance(c,Node): return c
        return None
    def descendants(self):
        yield self
        for c in self.children:
            if isinstance(c,Node):
                yield from c.descendants()
    def set_parents(self,parent=None):
        self.parent=parent
        for c in self.children:
            if isinstance(c,Node): c.set_parents(self)

class Lexer:
    def __init__(self, src):
        self.s=src
        self.n=len(src)
        self.i=0
        self.tokens=[]
        self.boffs=byte_offsets(src)
        # stack frames: dict with mode
        self.stack=[{'mode':'normal','interp':False,'brace':0}]
    def emit(self,kind,start,end):
        if start==end and kind not in ('TOKEN_EOF',): 
            return None
        t=Token(kind,start,end,self.s[start:end],self.boffs[start],self.boffs[end])
        self.tokens.append(t)
        return t
    def peekstr(self,k):
        return self.s[self.i:self.i+k]
