        t=self.peek_tok(k); return t.kind if t else None
    def at(self, kind):
        return self.peek_kind()==kind
    def bump(self):
        # consume next meaningful token
        while self.p < len(self.tokens) and self.tokens[self.p].kind in TRIVIA:
            self.p+=1
        if self.p>=len(self.tokens): return None
        t=self.tokens[self.p]; self.p+=1; self.last_end=t.end; return t
    def eat(self, kind):
        if self.at(kind): return self.bump()
        return None
    def byte_range_str(self, st, en):
        return f"{self.boffs[st]}..{self.boffs[en]}"
    def error_node(self, msg, start=0,end=0,children=None,silent=False):
        nd=Node('Error', children or [], _start=start,_end=end)
        nd.extra['msg']=msg; nd.extra['silent']=silent
        return nd
    def err_unexpected(self, wanted, consume=False):
        t=self.peek_tok()
        if t is None:
            if wanted:
                msg=f"Unexpected end of file, wanted any of {wanted}"
            else:
                msg="Unexpected end of file"
            return self.error_node(msg,0,0)
        msg=f"Unexpected {t.kind} at {t.bstart}..{t.bend}, wanted any of {wanted}" if wanted else f"Unexpected {t.kind} at {t.bstart}..{t.bend}"
        children=[]
        st,en=t.start,t.end
        if consume:
            children=[self.bump()]
        return self.error_node(msg,st,en,children)
    def expect(self, kind, wanted=None, generic_eof=False):
        if self.at(kind):
            return self.bump(), None
        t=self.peek_tok()
        if t is None:
            if generic_eof:
                return None, self.error_node("Unexpected end of file",0,0)
            return None, self.error_node(f"Unexpected end of file, wanted any of [{kind}]",0,0)
        # non-EOF mismatch: error, do not consume (delimiter recovery)
        return None, self.error_node(f"Unexpected {t.kind} at {t.bstart}..{t.bend}, wanted any of [{kind}]",t.start,t.end)
    def mk(self,kind,children,start=None,end=None,extra=None):
        nd=Node(kind, [c for c in children if c is not None], _start=start,_end=end)
        if extra: nd.extra.update(extra)
        nd.set_parents()
        return nd
    def parse(self):
        children=[]
        if self.peek_tok() is None:
            children.append(self.error_node("Unexpected end of file",0,0))
        else:
            expr=self.parse_expr()
            if expr is not None: children.append(expr)
            # trailing
            first=self.peek_tok()
            if first is not None:
                st=first.start; last=first
                toks=[]
                while self.peek_tok() is not None:
                    last=self.bump(); toks.append(last)
                err=self.error_node(f"Unexpected token at {self.boffs[st]}..{self.boffs[last.end]}", st,last.end,toks)
                children.append(err)
        root=self.mk('Root',children,start=0,end=len(self.src))
        root.set_parents(None)
        return root
    # -------- high level forms --------
    def parse_expr(self):
        # lambda pattern / ident
        t=self.peek_tok()
        if t is None:
            return self.error_node("Unexpected end of file",0,0)
        if t.kind=='TOKEN_LET':
            return self.parse_let()
        if t.kind=='TOKEN_IF':
            return self.parse_if()
        if t.kind=='TOKEN_ASSERT':
            return self.parse_assert()
        if t.kind=='TOKEN_WITH':
            return self.parse_with()
        if t.kind=='TOKEN_IDENT':
            k2=self.peek_kind(1)
            if k2=='TOKEN_COLON':
                return self.parse_lambda_ident()
            if k2=='TOKEN_AT' and self.peek_kind(2)=='TOKEN_L_BRACE' and self.lookahead_pattern_at(2):
                return self.parse_lambda_pattern()
        if t.kind=='TOKEN_L_BRACE' and self.is_pattern_start():
            return self.parse_lambda_pattern()
        return self.parse_op()
    def parse_lambda_ident(self):
        ident_tok=self.bump(); idnode=self.mk('Ident',[ident_tok])
        colon=self.bump(); body=self.parse_expr()
        return self.mk('Lambda',[idnode,colon,body])
    def meaningful_tokens_from(self, start_raw=None):
        # list of meaningful tokens starting at current p
        res=[]; idx=self.p if start_raw is None else start_raw
        while idx < len(self.tokens):
            t=self.tokens[idx]
            if t.kind not in TRIVIA: res.append(t)
            idx+=1
        return res
    def lookahead_pattern_at(self, offset_meaningful):
        toks=self.meaningful_tokens_from()
        i=offset_meaningful
        if i>=len(toks) or toks[i].kind!='TOKEN_L_BRACE': return False
        return self._pattern_content_ok(toks,i)[0]
    def is_pattern_start(self):
        toks=self.meaningful_tokens_from()
        if not toks or toks[0].kind!='TOKEN_L_BRACE': return False
        ok, close_idx, empty = self._pattern_content_ok(toks,0)
        if not ok: return False
        if empty:
            # only if followed by colon or @ ident colon
            if close_idx+1 < len(toks) and toks[close_idx+1].kind in ('TOKEN_COLON','TOKEN_AT'):
                return True
            return False
        return True
    def _pattern_content_ok(self,toks,i):
        # toks[i] is {
        j=i+1; empty=True
        if j < len(toks) and toks[j].kind=='TOKEN_R_BRACE':
            return True,j,True
        while j < len(toks):
            t=toks[j]
            if t.kind=='TOKEN_ELLIPSIS':
                empty=False; j+=1
                if j < len(toks) and toks[j].kind=='TOKEN_COMMA': j+=1; continue
                if j < len(toks) and toks[j].kind=='TOKEN_R_BRACE': return True,j,empty
                return False,j,empty
            if t.kind!='TOKEN_IDENT':
                return False,j,empty
            empty=False; j+=1
            if j < len(toks) and toks[j].kind=='TOKEN_QUESTION':
                # skip default until comma/rbrace at depth 0
                j+=1; depth=0; found=False
                while j < len(toks):
                    k=toks[j].kind
                    if depth==0 and k in ('TOKEN_COMMA','TOKEN_R_BRACE'):
                        found=True; break
                    if k in ('TOKEN_L_BRACE','TOKEN_L_PAREN','TOKEN_L_BRACK','TOKEN_INTERPOL_START'): depth+=1
                    elif k in ('TOKEN_R_BRACE','TOKEN_R_PAREN','TOKEN_R_BRACK','TOKEN_INTERPOL_END'):
                        if depth==0:
                            found=True; break
                        depth-=1
                    j+=1
                if not found: return False,j,empty
            if j < len(toks) and toks[j].kind=='TOKEN_COMMA':
                j+=1
                if j < len(toks) and toks[j].kind=='TOKEN_R_BRACE': return True,j,empty
                continue
            if j < len(toks) and toks[j].kind=='TOKEN_R_BRACE':
                return True,j,empty
            return False,j,empty
        return False,j,empty
    def parse_lambda_pattern(self):
        pat=self.parse_pattern()
        colon,err=self.expect('TOKEN_COLON')
        children=[pat]
        if err: children.append(err)
        if colon: children.append(colon)
        body=self.parse_expr() if not (err and self.peek_tok() is None and False) else None
        # Reference for {a} at EOF: errors are wanted COLON and one generic EOF (body)
        if body is not None: children.append(body)
        return self.mk('Lambda',children)
    def parse_pattern(self):
        # forms: { ... } [@ ident]   or ident @ { ... }
        children=[]; bind=None; entries=[]; ellipsis=False
        if self.at('TOKEN_IDENT') and self.peek_kind(1)=='TOKEN_AT':
            idtok=self.bump(); idnode=self.mk('Ident',[idtok]); bind=idnode; children.append(idnode)
            children.append(self.bump()) # @
            entries_children, entries, ellipsis = self.parse_pattern_braces()
            children.extend(entries_children)
        else:
            entries_children, entries, ellipsis = self.parse_pattern_braces()
            children.extend(entries_children)
            if self.at('TOKEN_AT'):
                children.append(self.bump())
                if self.at('TOKEN_IDENT'):
                    idtok=self.bump(); idnode=self.mk('Ident',[idtok]); bind=idnode; children.append(idnode)
                else:
                    children.append(self.err_unexpected("[TOKEN_IDENT]"))
        pat=self.mk('Pattern',children,extra={'bind':bind,'entries':entries,'ellipsis':ellipsis})
        return pat
    def parse_pattern_braces(self):
        children=[]; entries=[]; ellipsis=False
        lb,err=self.expect('TOKEN_L_BRACE')
        if lb: children.append(lb)
        if err: children.append(err)
        while not self.at('TOKEN_R_BRACE') and self.peek_tok() is not None:
            if self.at('TOKEN_ELLIPSIS'):
                children.append(self.bump()); ellipsis=True
                if self.at('TOKEN_COMMA'): children.append(self.bump())
                continue
            if not self.at('TOKEN_IDENT'):
                # error consume one token to progress
                children.append(self.err_unexpected("[TOKEN_IDENT]",consume=True))
                if self.at('TOKEN_COMMA'): children.append(self.bump())
                continue
            idtok=self.bump(); entry_children=[idtok]
            default=None
            if self.at('TOKEN_QUESTION'):
                entry_children.append(self.bump()); default=self.parse_expr(); entry_children.append(default)
            entry=self.mk('PatEntry',entry_children)
            entries.append(entry); children.append(entry)
            if self.at('TOKEN_COMMA'):
                children.append(self.bump()); continue
            break
        rb,err=self.expect('TOKEN_R_BRACE')
        if rb: children.append(rb)
        if err: children.append(err)
        return children,entries,ellipsis
    def parse_let(self):
        let_tok=self.bump()
        if self.at('TOKEN_L_BRACE'):
            lb=self.bump(); children=[let_tok,lb]; entries=[]
            while not self.at('TOKEN_R_BRACE') and self.peek_tok() is not None:
                e=self.parse_entry(); entries.append(e); children.append(e)
            rb,err=self.expect('TOKEN_R_BRACE',generic_eof=True)
            if rb: children.append(rb)
            if err: children.append(err)
            return self.mk('LegacyLet',children,extra={'entries':entries})
        children=[let_tok]; entries=[]
        while not self.at('TOKEN_IN') and self.peek_tok() is not None:
            before=self.p
            e=self.parse_entry(); entries.append(e); children.append(e)
            if self.p==before:
                # consume one to avoid loop
                t=self.bump()
                if t: children.append(t)
        intok,err=self.expect('TOKEN_IN',generic_eof=True)
        if err: children.append(err)
        if intok: children.append(intok)
        body=self.parse_expr(); children.append(body)
        node=self.mk('LetIn',children,extra={'entries':entries,'body':body,'in_tok':intok,'let_tok':let_tok})
        return node
    def parse_entry(self):
        if self.at('TOKEN_INHERIT'):
            return self.parse_inherit()
        return self.parse_bind()
    def parse_if(self):
        iftok=self.bump(); cond=self.parse_expr()
        then_tok,err1=self.expect('TOKEN_THEN')
        then_e=self.parse_expr()
        else_tok,err2=self.expect('TOKEN_ELSE')
        else_e=self.parse_expr()
        children=[iftok,cond]
        if err1: children.append(err1)
        if then_tok: children.append(then_tok)
        children.append(then_e)
        if err2: children.append(err2)
        if else_tok: children.append(else_tok)
        children.append(else_e)
        return self.mk('If',children,extra={'cond':cond,'then':then_e,'else':else_e})
    def parse_assert(self):
        tok=self.bump(); cond=self.parse_expr(); semi,err=self.expect('TOKEN_SEMICOLON'); body=self.parse_expr()
        ch=[tok,cond]
        if err: ch.append(err)
        if semi: ch.append(semi)
        ch.append(body); return self.mk('Assert',ch,extra={'cond':cond,'body':body})
    def parse_with(self):
        tok=self.bump(); set_e=self.parse_expr(); semi,err=self.expect('TOKEN_SEMICOLON'); body=self.parse_expr()
        ch=[tok,set_e]
        if err: ch.append(err)
        if semi: ch.append(semi)
        ch.append(body); return self.mk('With',ch,extra={'set':set_e,'body':body})
    # -------- operators --------
    def parse_op(self): return self.parse_implies()
    def bin(self,lhs,op,rhs):
        return self.mk('BinOp',[lhs,op,rhs],extra={'op':op,'lhs':lhs,'rhs':rhs})
    def parse_implies(self):
        lhs=self.parse_or_op()
        if self.at('TOKEN_IMPLIES'):
            op=self.bump(); rhs=self.parse_implies(); return self.bin(lhs,op,rhs)
        return lhs
    def parse_or_op(self):
        lhs=self.parse_and_op()
        while self.at('TOKEN_OR_OP'):
            op=self.bump(); rhs=self.parse_and_op(); lhs=self.bin(lhs,op,rhs)
        return lhs
    def parse_and_op(self):
        lhs=self.parse_equality()
        while self.at('TOKEN_AND'):
            op=self.bump(); rhs=self.parse_equality(); lhs=self.bin(lhs,op,rhs)
        return lhs
    def parse_equality(self):
        lhs=self.parse_rel()
        if self.peek_kind() in ('TOKEN_EQUAL','TOKEN_NOT_EQUAL'):
            op=self.bump(); rhs=self.parse_rel(); return self.bin(lhs,op,rhs)
        return lhs
    def parse_rel(self):
        lhs=self.parse_update()
        if self.peek_kind() in ('TOKEN_LESS','TOKEN_LESS_EQ','TOKEN_GREATER','TOKEN_GREATER_EQ'):
            op=self.bump(); rhs=self.parse_update(); return self.bin(lhs,op,rhs)
        return lhs
    def parse_update(self):
        lhs=self.parse_not()
        if self.at('TOKEN_UPDATE'):
            op=self.bump(); rhs=self.parse_update(); return self.bin(lhs,op,rhs)
        return lhs
    def parse_not(self):
        if self.at('TOKEN_INVERT'):
            op=self.bump(); val=self.parse_not(); return self.mk('UnaryOp',[op,val],extra={'op':op,'value':val})
        return self.parse_add()
    def parse_add(self):
        lhs=self.parse_mul()
        while self.peek_kind() in ('TOKEN_PLUS','TOKEN_SUB'):
            op=self.bump(); rhs=self.parse_mul(); lhs=self.bin(lhs,op,rhs)
        return lhs
    def parse_mul(self):
        lhs=self.parse_concat()
        while self.peek_kind() in ('TOKEN_MUL','TOKEN_DIV'):
            op=self.bump(); rhs=self.parse_concat(); lhs=self.bin(lhs,op,rhs)
        return lhs
    def parse_concat(self):
        lhs=self.parse_hasattr()
        if self.at('TOKEN_CONCAT'):
            op=self.bump(); rhs=self.parse_concat(); return self.bin(lhs,op,rhs)
        return lhs
    def parse_hasattr(self):
        lhs=self.parse_neg()
        while self.at('TOKEN_QUESTION'):
            q=self.bump(); key=self.parse_key()
            lhs=self.mk('HasAttr',[lhs,q,key],extra={'set':lhs,'key':key})
        return lhs
    def parse_neg(self):
        if self.at('TOKEN_SUB'):
            op=self.bump(); val=self.parse_neg(); return self.mk('UnaryOp',[op,val],extra={'op':op,'value':val})
        return self.parse_app()
    def can_start_simple(self):
        k=self.peek_kind()
        return k in ('TOKEN_IDENT','TOKEN_INTEGER','TOKEN_FLOAT','TOKEN_URI','TOKEN_PATH','TOKEN_SPATH','TOKEN_STRING_START','TOKEN_L_PAREN','TOKEN_L_BRACE','TOKEN_REC','TOKEN_L_BRACK')
    def parse_app(self):
        lhs=self.parse_select()
        while self.can_start_simple():
            arg=self.parse_select()
            lhs=self.mk('Apply',[lhs,arg],extra={'func':lhs,'arg':arg})
        return lhs
    def parse_select(self):
        base=self.parse_simple()
        # selection chaining
        while self.at('TOKEN_DOT'):
            # parse one select with full attrpath
            # consume first dot inside parse_key_with_leading_dot?
            key_children=[]; attrs=[]
            while self.at('TOKEN_DOT'):
                dot=self.bump(); key_children.append(dot)
                attr=self.parse_attr(); attrs.append(attr); key_children.append(attr)
            key=self.mk('Key',key_children,extra={'attrs':attrs})
            children=[base,key]; default=None; or_tok=None
            if self.at('TOKEN_OR'):
                or_tok=self.bump(); children.append(or_tok)
                default=self.parse_app(); children.append(default)
            base=self.mk('Select',children,extra={'set':children[0],'key':key,'default':default})
            # loop in case another dot follows after default-less select (but key consumed all dots; after default parse_app consumed its own selects)
            if default is not None:
                break
        return base
    # -------- simple values --------
    def parse_simple(self):
        t=self.peek_tok()
        if t is None:
            return self.error_node("Unexpected end of file",0,0)
        k=t.kind
        if k=='TOKEN_IDENT':
            tok=self.bump(); return self.mk('Ident',[tok])
        if k in ('TOKEN_INTEGER','TOKEN_FLOAT','TOKEN_SPATH','TOKEN_URI'):
            tok=self.bump(); return self.mk('Literal',[tok],extra={'tok_kind':k})
        if k=='TOKEN_PATH':
            children=[]; 
            while True:
                if self.at('TOKEN_PATH'):
                    children.append(self.bump()); continue
                if self.at('TOKEN_INTERPOL_START'):
                    children.append(self.parse_dynamic()); continue
                break
            return self.mk('Literal',children,extra={'tok_kind':'TOKEN_PATH'})
        if k=='TOKEN_STRING_START':
            return self.parse_string()
        if k=='TOKEN_L_PAREN':
            lp=self.bump(); inner=self.parse_expr(); rp,err=self.expect('TOKEN_R_PAREN',generic_eof=True)
            ch=[lp,inner]
            if err: ch.append(err)
            if rp: ch.append(rp)
            return self.mk('Paren',ch,extra={'inner':inner})
        if k=='TOKEN_L_BRACE' or k=='TOKEN_REC':
            return self.parse_attrset()
        if k=='TOKEN_L_BRACK':
            return self.parse_list()
        # invalid primary: consume token
        err=self.err_unexpected(PRIMARY_WANTED,consume=True)
        return err
    def parse_string(self):
        start=self.bump(); children=[start]; valid_end=False; had_error_token=False
        while True:
            t=self.peek_tok()
            if t is None:
                # add EOF errors similar to reference: wanted parts then wanted end (unless just after interpol? approximate)
                children.append(self.error_node("Unexpected end of file, wanted any of [TOKEN_STRING_END, TOKEN_STRING_CONTENT, TOKEN_INTERPOL_START]",0,0))
                children.append(self.error_node("Unexpected end of file, wanted any of [TOKEN_STRING_END]",0,0))
                break
            if t.kind=='TOKEN_STRING_END':
                children.append(self.bump()); valid_end=True; break
            if t.kind=='TOKEN_STRING_CONTENT':
                children.append(self.bump()); continue
            if t.kind=='TOKEN_INTERPOL_START':
                children.append(self.parse_dynamic(in_string=True)); continue
            if t.kind=='TOKEN_ERROR':
                # consume and error like reference
                tok=self.bump(); had_error_token=True
                children.append(self.error_node(f"Unexpected TOKEN_ERROR at {tok.bstart}..{tok.bend}, wanted any of [TOKEN_STRING_END, TOKEN_STRING_CONTENT, TOKEN_INTERPOL_START]",tok.start,tok.end,[tok]))
                # then loop will hit EOF or next
                continue
            # unexpected token inside string (shouldn't happen due lexer mode)
            children.append(self.err_unexpected("[TOKEN_STRING_END, TOKEN_STRING_CONTENT, TOKEN_INTERPOL_START]",consume=True))
        return self.mk('String',children)
    def parse_dynamic(self,in_string=False):
        start=self.bump(); children=[start]
        if self.at('TOKEN_INTERPOL_END'):
            if in_string:
                # produce primary error like parse of empty expr
                children.append(self.err_unexpected(PRIMARY_WANTED,consume=False))
                # reference then expects interpol-end but sees string-end etc; approximate by consuming end as part? 
                # consume interpol end token to progress
                # Actually err_unexpected above uses interpol end token; then expect INTERPOL_END will consume it (reference does not, but close enough)
            else:
                # dynamic empty accepted in attr keys by reference; silent empty node
                children.append(self.error_node("",self.peek_tok().start,self.peek_tok().start,silent=True))
        else:
            expr=self.parse_expr(); children.append(expr)
        endtok,err=self.expect('TOKEN_INTERPOL_END')
        if err: children.append(err)
        if endtok: children.append(endtok)
        Dyn=self.mk('Dynamic',children)
        return Dyn
    def parse_list(self):
        lb=self.bump(); children=[lb]; elems=[]
        while not self.at('TOKEN_R_BRACK') and self.peek_tok() is not None:
            # element: select-level with optional neg/hasattr, but not application
            elem=self.parse_list_element(); elems.append(elem); children.append(elem)
            if elem.kind=='Error' and elem.start==0 and elem.end==0:
                break
        rb,err=self.expect('TOKEN_R_BRACK',generic_eof=True)
        if err: children.append(err)
        if rb: children.append(rb)
        return self.mk('List',children,extra={'elems':elems})
    def parse_list_element(self):
        if self.at('TOKEN_SUB'):
            op=self.bump(); val=self.parse_list_element(); return self.mk('UnaryOp',[op,val],extra={'op':op,'value':val})
        # if ! in list? list element grammar may not allow; parse_simple will error
        val=self.parse_select()
        if self.at('TOKEN_QUESTION'):
            q=self.bump(); key=self.parse_key(); val=self.mk('HasAttr',[val,q,key],extra={'set':val,'key':key})
        return val
    def parse_attrset(self):
        children=[]; rec=False
        if self.at('TOKEN_REC'):
            children.append(self.bump()); rec=True
        lb,err=self.expect('TOKEN_L_BRACE',generic_eof=True)
        if lb: children.append(lb)
        if err: children.append(err)
        entries=[]
        while not self.at('TOKEN_R_BRACE') and self.peek_tok() is not None:
            before=self.p
            e=self.parse_entry(); entries.append(e); children.append(e)
            if self.p==before:
                t=self.bump()
                if t: children.append(t)
        rb,err=self.expect('TOKEN_R_BRACE',generic_eof=True)
        if err: children.append(err)
        if rb: children.append(rb)
        return self.mk('AttrSet',children,extra={'entries':entries,'rec':rec})
    def parse_bind(self):
        key=self.parse_key(); children=[key]
        assign,err=self.expect('TOKEN_ASSIGN')
        if err: children.append(err)
        if assign: children.append(assign)
        value=None
        if assign:
            value=self.parse_expr(); children.append(value)
        semi,err2=self.expect('TOKEN_SEMICOLON')
        if err2: children.append(err2)
        if semi: children.append(semi)
        return self.mk('Bind',children,extra={'key':key,'value':value})
    def parse_inherit(self):
        inh=self.bump(); children=[inh]; source=None; from_paren=False
        if self.at('TOKEN_L_PAREN'):
            from_paren=True; children.append(self.bump()); source=self.parse_expr(); children.append(source)
            rp,err=self.expect('TOKEN_R_PAREN',generic_eof=True)
            if err: children.append(err)
            if rp: children.append(rp)
        attrs=[]
        while not self.at('TOKEN_SEMICOLON') and not self.at('TOKEN_R_BRACE') and not self.at('TOKEN_IN') and self.peek_tok() is not None:
            a=self.parse_attr(); attrs.append(a); children.append(a)
            if a.kind=='Attr' and a.child_nodes() and a.child_nodes()[0].kind=='Error':
                # parse_attr consumed problematic token; continue maybe
                pass
        semi,err=self.expect('TOKEN_SEMICOLON')
        if err: children.append(err)
        if semi: children.append(semi)
        return self.mk('Inherit',children,extra={'source':source,'attrs':attrs,'has_from':from_paren})
    def parse_key(self):
        children=[]; attrs=[]
        a=self.parse_attr(); attrs.append(a); children.append(a)
        while self.at('TOKEN_DOT'):
