# ---------- parser ----------
TRIVIA={'TOKEN_WHITESPACE','TOKEN_COMMENT'}
class Parser:
    def __init__(self, src):
        self.src=src
        self.lexer=Lexer(src)
        self.tokens=self.lexer.tokenize()
        self.boffs=self.lexer.boffs
        self.p=0
        self.last_end=0
    # token navigation
    def peek_tok(self, k=0):
        idx=self.p; seen=-1
        while idx < len(self.tokens):
            t=self.tokens[idx]
            if t.kind not in TRIVIA:
                seen+=1
                if seen==k: return t
            idx+=1
        return None
    def peek_kind(self, k=0):
        t=self.peek_tok(k); return t.kind if t else None
    def at(self, kind):
        return self.peek_kind()==kind
    def bump(self):
        # consume next meaningful token
        while self.p < len(self.tokens) and self.tokens[self.p].kind in TRIVIA:
            self.p+=1
        if self.p>=len(self.tokens): return None
        t=self.tokens[self.p]; self.p+=1; self.last_end=t.end; return t
    def eat(self, kind):
        if self.at(kind): return self.bump()
        return None
    def byte_range_str(self, st, en):
        return f"{self.boffs[st]}..{self.boffs[en]}"
    def error_node(self, msg, start=0,end=0,children=None,silent=False):
        nd=Node('Error', children or [], _start=start,_end=end)
        nd.extra['msg']=msg; nd.extra['silent']=silent
        return nd
    def err_unexpected(self, wanted, consume=False):
        t=self.peek_tok()
        if t is None:
            if wanted:
                msg=f"Unexpected end of file, wanted any of {wanted}"
            else:
                msg="Unexpected end of file"
            return self.error_node(msg,0,0)
        msg=f"Unexpected {t.kind} at {t.bstart}..{t.bend}, wanted any of {wanted}" if wanted else f"Unexpected {t.kind} at {t.bstart}..{t.bend}"
        children=[]
        st,en=t.start,t.end
        if consume:
            children=[self.bump()]
        return self.error_node(msg,st,en,children)
    def expect(self, kind, wanted=None, generic_eof=False):
        if self.at(kind):
            return self.bump(), None
        t=self.peek_tok()
        if t is None:
            if generic_eof:
                return None, self.error_node("Unexpected end of file",0,0)
            return None, self.error_node(f"Unexpected end of file, wanted any of [{kind}]",0,0)
        # non-EOF mismatch: error, do not consume (delimiter recovery)
        return None, self.error_node(f"Unexpected {t.kind} at {t.bstart}..{t.bend}, wanted any of [{kind}]",t.start,t.end)
    def mk(self,kind,children,start=None,end=None,extra=None):
        nd=Node(kind, [c for c in children if c is not None], _start=start,_end=end)
        if extra: nd.extra.update(extra)
        nd.set_parents()
        return nd
    def parse(self):
        children=[]
        if self.peek_tok() is None:
            children.append(self.error_node("Unexpected end of file",0,0))
        else:
            expr=self.parse_expr()
            if expr is not None: children.append(expr)
