                err=self.error_node(f"Unexpected token at {self.boffs[st]}..{self.boffs[last.end]}", st,last.end,toks)
                children.append(err)
        root=self.mk('Root',children,start=0,end=len(self.src))
        root.set_parents(None)
        return root
