    def parse_expr(self):
        # lambda pattern / ident
        t=self.peek_tok()
        if t is None:
            return self.error_node("Unexpected end of file",0,0)
        if t.kind=='TOKEN_LET':
            return self.parse_let()
        if t.kind=='TOKEN_IF':
            return self.parse_if()
        if t.kind=='TOKEN_ASSERT':
            return self.parse_assert()
        if t.kind=='TOKEN_WITH':
            return self.parse_with()
