        pat=self.parse_pattern()
        colon,err=self.expect('TOKEN_COLON')
        children=[pat]
        if err: children.append(err)
        if colon: children.append(colon)
        body=self.parse_expr() if not (err and self.peek_tok() is None and False) else None
