        if t is None:
            if generic_eof:
                return None, self.error_node("Unexpected end of file",0,0)
            return None, self.error_node(f"Unexpected end of file, wanted any of [{kind}]",0,0)
        # non-EOF mismatch: error, do not consume (delimiter recovery)
        return None, self.error_node(f"Unexpected {t.kind} at {t.bstart}..{t.bend}, wanted any of [{kind}]",t.start,t.end)
    def mk(self,kind,children,start=None,end=None,extra=None):
        nd=Node(kind, [c for c in children if c is not None], _start=start,_end=end)
        if extra: nd.extra.update(extra)
        nd.set_parents()
        return nd
    def parse(self):
        children=[]
        if self.peek_tok() is None:
            children.append(self.error_node("Unexpected end of file",0,0))
        else:
            expr=self.parse_expr()
            if expr is not None: children.append(expr)
