                children.append(self.error_node("Unexpected end of file, wanted any of [TOKEN_STRING_END, TOKEN_STRING_CONTENT, TOKEN_INTERPOL_START]",0,0))
                children.append(self.error_node("Unexpected end of file, wanted any of [TOKEN_STRING_END]",0,0))
