                pass
        semi,err=self.expect('TOKEN_SEMICOLON')
        if err: children.append(err)
        if semi: children.append(semi)
        return self.mk('Inherit',children,extra={'source':source,'attrs':attrs,'has_from':from_paren})
    def parse_key(self):
        children=[]; attrs=[]
        a=self.parse_attr(); attrs.append(a); children.append(a)
        while self.at('TOKEN_DOT'):
            children.append(self.bump()); a=self.parse_attr(); attrs.append(a); children.append(a)
        return self.mk('Key',children,extra={'attrs':attrs})
    def parse_attr(self):
        t=self.peek_tok()
        if t is None:
            e=self.error_node("Unexpected end of file, wanted any of [TOKEN_IDENT, TOKEN_OR]",0,0)
            return self.mk('Attr',[e])
        if t.kind in ('TOKEN_IDENT','TOKEN_OR'):
            tok=self.bump(); return self.mk('Attr',[tok])
        if t.kind=='TOKEN_STRING_START':
            s=self.parse_string(); return self.mk('Attr',[s])
        if t.kind=='TOKEN_INTERPOL_START':
            d=self.parse_dynamic(); return self.mk('Attr',[d])
        # invalid: consume one (and possibly following tokens are handled by caller)
        err=self.err_unexpected("[TOKEN_IDENT, TOKEN_OR]",consume=True)
        return self.mk('Attr',[err])

def parse_source(src):
    parser=Parser(src)
    root=parser.parse()
    return parser,root
