    if codes[0][0]=='equal':
        tag,i1,i2,j1,j2=codes[0]
        codes[0]=(tag,max(i1,i2-context),i2,max(j1,j2-context),j2)
    if codes[-1][0]=='equal':
        tag,i1,i2,j1,j2=codes[-1]
        codes[-1]=(tag,i1,min(i2,i1+context),j1,min(j2,j1+context))
    nn=context*2
    group=[]
    for tag,i1,i2,j1,j2 in codes:
        if tag=='equal' and i2-i1>nn:
            group.append((tag,i1,min(i2,i1+context),j1,min(j2,j1+context)))
            groups.append(group[:]); group=[]
            i1,j1=max(i1,i2-context),max(j1,j2-context)
        group.append((tag,i1,i2,j1,j2))
    if group and not (len(group)==1 and group[0][0]=='equal'):
        groups.append(group)
    out=[]
    out.append(f"--- {path}\n"); out.append(f"+++ {path} [fixed]\n")
    for group in groups:
        first=group[0]; last=group[-1]
        old_start=first[1]; old_end=last[2]; new_start=first[3]; new_end=last[4]
        old_count=old_end-old_start; new_count=new_end-new_start
        def rng(start,count):
            if count==1:
                return f"{start+1}"
            if count==0:
                return f"{start},0"
            return f"{start+1},{count}"
        out.append(f"@@ -{rng(old_start,old_count)} +{rng(new_start,new_count)} @@\n")
        for tag,i1,i2,j1,j2 in group:
            if tag=='equal':
                for line in old_lines[i1:i2]:
                    text=line[:-1] if line.endswith('\n') else line
                    out.append(' '+text+'\n')
                    if not line.endswith('\n'):
                        out.append('\\ No newline at end of file\n')
                continue
            if tag in ('replace','delete'):
                for line in old_lines[i1:i2]:
                    text=line[:-1] if line.endswith('\n') else line
                    out.append('-'+text+'\n')
                    if not line.endswith('\n'):
                        out.append('\\ No newline at end of file\n')
            if tag in ('replace','insert'):
                for line in new_lines[j1:j2]:
                    text=line[:-1] if line.endswith('\n') else line
                    out.append('+'+text+'\n')
                    if not line.endswith('\n'):
                        out.append('\\ No newline at end of file\n')
    return "".join(out)
