# ---------- errfmt, fix, diff ----------
def split_lines_keep(s):
    if s=="": return []
    parts=s.split('\n')
    lines=[]
    for idx,p in enumerate(parts):
        if idx < len(parts)-1:
            lines.append(p+'\n')
        else:
            if p!="":
                lines.append(p)
    return lines

def line_col_from_char(src,boffs,char_pos,bpos):
    # line (1-indexed) by counting \n before char_pos
    upto=src[:char_pos]
    line=upto.count('\n')+1
    last_nl=upto.rfind('\n')
    line_start_char=last_nl+1
    col=bpos - boffs[line_start_char] + 1
    return line,col

def format_errfmt(diags,src,boffs):
    out=[]
    for d in diags:
        for lab in d.labels:
            line,col=line_col_from_char(src,boffs,lab.start,lab.bstart)
            out.append(f"{d.path}>{line}:{col}:{d.severity}:{d.code}:{lab.note}\n")
    return "".join(out)

def apply_edit(src,edit):
    return src[:edit.start]+edit.replacement+src[edit.end:]

def apply_edits(src,edits):
    # edits already selected, apply right-to-left
    for e in sorted(edits,key=lambda e:(e.start,e.end),reverse=True):
        src=src[:e.start]+e.replacement+src[e.end:]
    return src

def fix_once(src,disabled=None,path='<stdin>'):
    parser,root,diags=analyze_source(src,path,disabled)
    if any(d.severity=='E' for d in diags):
        return src
    candidates=[]
    for idx,d in enumerate(diags):
        if d.suggestion is not None:
            candidates.append((d.suggestion.bend,d.suggestion.bstart,idx,d.suggestion))
    candidates.sort(key=lambda x:(x[0],x[1],x[2]))
    selected=[]
    for _,_,_,e in candidates:
        overlap=False
        for s in selected:
            if max(e.start,s.start) < min(e.end,s.end):
                overlap=True; break
            # identical range also overlaps unless zero-length (covered)
            if e.start==s.start and e.end==s.end:
                overlap=True; break
        if not overlap:
            selected.append(e)
    return apply_edits(src,selected)

def fix_all(src,disabled=None,path='<stdin>'):
    seen=set()
    cur=src
    for _ in range(10000):
        nxt=fix_once(cur,disabled,path)
        if nxt==cur:
            return cur
        if nxt in seen:
            return nxt
        seen.add(cur)
        cur=nxt
    return cur

