def position_to_byte(src,boffs,line,col):
    # lines as Rust str.lines() (split on \n, trailing \r stripped for content but start offsets by \n)
    if src=="":
        lines=[]
    else:
        parts=src.split('\n')
        if src.endswith('\n'):
            parts=parts[:-1]
