        lines=parts
    line_idx=line-1 if line>0 else 0
    if line_idx >= len(lines):
        raise SingleError(f"position out of bounds: line {line}, col {col}")
    # char start of line
    char_start=0
    # compute by finding the (line_idx)th newline
    idx=0; cnt=0
    while cnt<line_idx:
