# ---------- errors, config ----------
class SessionError(Exception): pass
class FixerError(Exception): pass

def format_os_error(e):
    if getattr(e,'errno',None) is not None:
        msg=e.strerror or str(e)
        return f"{msg} (os error {e.errno})"
    return str(e)

def panic_exit(location,msg):
    try: sys.stdout.flush()
    except Exception: pass
    pid=os.getpid()
    sys.stderr.write(f"\nthread 'main' ({pid}) panicked at {location}:\n{msg}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.stderr.flush()
    raise SystemExit(101)

def read_file_text_for_config(path):
    try:
        with open(path,'rb') as f: data=f.read()
    except OSError as e:
        raise SessionError(f"path error: {format_os_error(e)}")
    try:
        return data.decode('utf-8')
    except UnicodeDecodeError:
        raise SessionError("path error: stream did not contain valid UTF-8")

# --- minimal TOML parser for config ---
class TomlErrorMsg(Exception): pass
@dataclass
class TValue:
    value: object
    kind: str  # string, integer, float, boolean, sequence, map, datetime
    start: int
    raw: str = ''
    frac_start: int = None

class TomlParser:
    def __init__(self,src):
        self.s=src; self.n=len(src); self.i=0
        self.top={}  # name->TValue for top-level scalar assignments (only first segment handling)
        self.fields={} # disabled/ignore if top level
        self.section=''
        self.explicit_sections=set()
    def linecol(self,idx):
        idx=max(0,min(idx,self.n))
        upto=self.s[:idx]; line=upto.count('\n')+1; ls=upto.rfind('\n')+1; return line,idx-ls+1
    def err(self,msg,idx=None):
        if idx is None: idx=self.i
        line,col=self.linecol(idx)
        raise TomlErrorMsg(f"{msg} at line {line} column {col}")
    def skip_ws(self):
        while self.i<self.n and self.s[self.i] in ' \t': self.i+=1
    def skip_ws_comments_newlines(self):
        while self.i<self.n:
            c=self.s[self.i]
            if c in ' \t\r\n': self.i+=1; continue
            if c=='#':
                while self.i<self.n and self.s[self.i]!='\n': self.i+=1
                continue
            break
    def parse(self):
        while True:
            self.skip_ws_comments_newlines()
            if self.i>=self.n: break
            if self.s[self.i]=='[':
                self.parse_header()
            else:
                self.parse_keyval()
            # after expression, expect newline/eof/comment
            self.skip_ws()
            if self.i<self.n and self.s[self.i]=='#':
                while self.i<self.n and self.s[self.i]!='\n': self.i+=1
            if self.i<self.n and self.s[self.i] not in '\r\n':
                # determine found token
                self.err("expected newline, found "+self.token_desc(),self.i)
        return self.fields
    def token_desc(self):
        if self.i>=self.n: return "a newline"
        c=self.s[self.i]
        if c=='\n': return "a newline"
        if c=='=': return "an equals"
        if c.isalnum() or c in '_-': return "an identifier"
        if c==']': return "a right bracket"
        return f"`{c}`"
    def parse_header(self):
        start=self.i
        is_array=self.s.startswith('[[',self.i)
        self.i+=2 if is_array else 1
        self.skip_ws()
        key_start=self.i
        # read until ]
        key=self.parse_key_path(stop_at_bracket=True)
        self.skip_ws()
        if self.i>=self.n or self.s[self.i]!=' ]'.strip():
            # check ]
            if self.i>=self.n or self.s[self.i]!=']':
                self.err("expected a right bracket, found "+("a newline" if self.i<self.n and self.s[self.i]=='\n' else self.token_desc()),self.i if self.i<self.n else self.n)
        self.i+=1
        if is_array:
            if self.i<self.n and self.s[self.i]==']': self.i+=1
        sec='.'.join(key)
        if not is_array:
            if sec in self.explicit_sections:
                line,col=self.linecol(start)
                raise TomlErrorMsg(f"redefinition of table `{key[0] if key else sec}` for key `{key[0] if key else sec}` at line {line} column {col}")
            self.explicit_sections.add(sec)
        self.section=sec
        # if section is exactly disabled/ignore, record as map field
        if sec in ('disabled','ignore'):
            if sec in self.fields:
                raise TomlErrorMsg(f"duplicate field `{sec}` at line 1 column 1")
            self.fields[sec]=TValue({},'map',start)
    def parse_key_path(self,stop_at_bracket=False):
        parts=[]
        while True:
            self.skip_ws()
            if self.i>=self.n:
                self.err("expected a table key, found a newline",self.i)
            c=self.s[self.i]
            if c=='=':
                self.err("expected a table key, found an equals",self.i)
            if c in ('"',"'"):
                parts.append(self.parse_string_value().value)
            else:
                m=re.match(r'[A-Za-z0-9_-]+',self.s[self.i:])
                if not m:
                    self.err("expected a table key, found "+self.token_desc(),self.i)
                parts.append(m.group(0)); self.i+=m.end()
            self.skip_ws()
            if self.i<self.n and self.s[self.i]=='.':
                self.i+=1; continue
            break
        return parts
    def parse_keyval(self):
        start=self.i
        if self.s[self.i]=='=':
            self.err("expected a table key, found an equals",self.i)
        key=self.parse_key_path()
        self.skip_ws()
        if self.i>=self.n or self.s[self.i]!='=':
            self.err("expected an equals, found "+self.token_desc(),self.i if self.i<self.n else self.n)
        self.i+=1; self.skip_ws()
        val=self.parse_value()
        if self.section=='' and len(key)==1 and key[0] in ('disabled','ignore'):
            name=key[0]
            if name in self.fields:
                raise TomlErrorMsg(f"duplicate field `{name}` at line 1 column 1")
            self.fields[name]=val
        elif self.section=='' and len(key)>1 and key[0] in ('disabled','ignore'):
            # dotted into a field: treat as map field if absent
            name=key[0]
            if name not in self.fields:
                self.fields[name]=TValue({},'map',start)
    def parse_value(self):
        if self.i>=self.n:
            self.err("unexpected eof encountered",self.n)
        start=self.i; c=self.s[self.i]
        if self.s.startswith('"""',self.i) or self.s.startswith("'''",self.i) or c in ('"',"'"):
            return self.parse_string_value()
        if c=='[':
            return self.parse_array()
        if c=='{':
            return self.parse_inline_table()
