        if self.s.startswith('false',self.i) and self.word_boundary(self.i+5):
            self.i+=5; return TValue(False,'boolean',start,'false')
        # datetime (rough)
        m=re.match(r'\d{4}-\d{2}-\d{2}(?:[T ][0-9:.\-+Zz]*)?',self.s[self.i:])
        if m:
