                val=sign*int(body.replace('_',''),0)
            except Exception: val=0
            return TValue(val,'integer',start,txt)
        m=re.match(r'[+-]?(?:\d[\d_]*(?:\.\d[\d_]*)?(?:[eE][+-]?[\d_]+)?|inf|nan)',self.s[self.i:])
        if m:
            txt=m.group(0); self.i+=m.end()
            if '.' in txt or 'e' in txt or 'E' in txt or txt.lstrip('+-') in ('inf','nan'):
                try: fv=float(txt.replace('_',''))
                except Exception: fv=0.0
                frac=None
                if '.' in txt:
                    dot=txt.find('.'); 
                    # find first fractional digit
                    for k in range(dot+1,len(txt)):
                        if txt[k].isdigit(): frac=start+k; break
