        self.err("expected a value, found "+self.token_desc(),self.i)
    def word_boundary(self,j):
        return j>=self.n or not (self.s[j].isalnum() or self.s[j] in '_-')
    def parse_string_value(self):
        start=self.i; s=self.s
        if s.startswith('"""',self.i):
            end=s.find('"""',self.i+3)
            if end==-1: self.err("unexpected eof encountered",self.n)
            raw=s[self.i+3:end]; self.i=end+3
            return TValue(self.decode_basic(raw),'string',start,raw)
        if s.startswith("'''",self.i):
            end=s.find("'''",self.i+3)
            if end==-1: self.err("unexpected eof encountered",self.n)
            raw=s[self.i+3:end]; self.i=end+3
            return TValue(raw,'string',start,raw)
        quote=s[self.i]; self.i+=1; out_start=self.i; i=self.i
        while i<self.n:
            c=s[i]
            if c=='\n':
                self.err("newline in string found",i)  # err() appends at line... but message in reference already includes 'found'; adjust below
            if quote=='"' and c=='\\':
                i+=2; continue
            if c==quote:
                raw=s[out_start:i]; self.i=i+1
                val=self.decode_basic(raw) if quote=='"' else raw
                return TValue(val,'string',start,raw)
            i+=1
        self.err("unexpected eof encountered",self.n)
    def decode_basic(self,raw):
        try:
            return bytes(raw,'utf-8').decode('unicode_escape') if '\\' in raw else raw
        except Exception:
            return raw
    def parse_array(self):
        start=self.i; self.i+=1; vals=[]
        while True:
            self.skip_ws_comments_newlines()
            if self.i>=self.n:
                self.err("unexpected eof encountered",self.n)
            if self.s[self.i]==']':
                self.i+=1; break
            vals.append(self.parse_value())
            self.skip_ws_comments_newlines()
            if self.i<self.n and self.s[self.i]==',':
                self.i+=1; continue
            if self.i<self.n and self.s[self.i]==']':
                self.i+=1; break
            if self.i>=self.n:
                self.err("unexpected eof encountered",self.n)
            # else let loop handle/error
        return TValue(vals,'sequence',start)
    def parse_inline_table(self):
        start=self.i; self.i+=1; result={}
        self.skip_ws()
        if self.i<self.n and self.s[self.i]=='}':
            self.i+=1; return TValue(result,'map',start)
