            self.parse_key_path(); self.skip_ws()
            if self.i<self.n and self.s[self.i]=='=': self.i+=1
            self.skip_ws(); self.parse_value(); self.skip_ws()
            if self.i<self.n and self.s[self.i]==',':
                self.i+=1; self.skip_ws(); continue
            if self.i<self.n and self.s[self.i]=='}':
                self.i+=1; break
            break
        return TValue(result,'map',start)

def toml_type_error(field, val, expected, parser):
    # returns message string like Rust
    kind=val.kind
    if kind=='sequence':
        desc="sequence"; linecol=(1,1)
    elif kind=='map':
        desc="map"; linecol=parser.linecol(val.start)
    elif kind=='datetime':
        desc="map"; linecol=parser.linecol(val.start)
    elif kind=='string':
        desc=f'string "{val.value}"'; linecol=parser.linecol(val.start)
    elif kind=='integer':
        desc=f"integer `{val.value}`"; linecol=parser.linecol(val.start)
    elif kind=='boolean':
        desc=f"boolean `{'true' if val.value else 'false'}`"; linecol=parser.linecol(val.start)
    elif kind=='float':
        fv=val.value
        if fv==float('inf'): rep='inf'
        elif fv==float('-inf'): rep='-inf'
        elif math.isnan(fv): rep='NaN'
        elif fv==int(fv) and abs(fv)<1e16: rep=str(int(fv))
        else: rep=('%.15g' % fv)
        desc=f"floating point `{rep}`"
        linecol=parser.linecol(val.frac_start if val.frac_start is not None else val.start)
    else:
        desc=kind; linecol=parser.linecol(val.start)
    line,col=linecol
    return f"invalid type: {desc}, expected {expected} for key `{field}` at line {line} column {col}"

def parse_config_content(content):
    parser=TomlParser(content)
    try:
        fields=parser.parse()
    except TomlErrorMsg as e:
        msg=str(e)
        msg=msg.replace("newline in string found at line","newline in string found at line") # parser err formats already
        raise SessionError(f"unable to parse config file: {msg}")
    except SessionError:
        raise
    config={'disabled':[],'ignore':[]}
    for field in ('disabled','ignore'):
        if field in fields:
            val=fields[field]
            if val.kind!='sequence':
                raise SessionError("unable to parse config file: "+toml_type_error(field,val,"a sequence",parser))
            out=[]
            for el in val.value:
                if el.kind!='string':
                    raise SessionError("unable to parse config file: "+toml_type_error(field,el,"a string",parser))
                out.append(el.value)
            config[field]=out
    return config

def load_config(conf_path):
    # canonicalize-like existence check
    try:
        st=os.stat(conf_path)
    except OSError as e:
        raise SessionError(f"path error: {format_os_error(e)}")
    import stat as statmod
    if statmod.S_ISDIR(st.st_mode):
        candidate=os.path.join(conf_path,"statix.toml")
        if not os.path.exists(candidate):
            return {'disabled':[],'ignore':[]}
        content=read_file_text_for_config(candidate)
        return parse_config_content(content)
    else:
        content=read_file_text_for_config(conf_path)
        return parse_config_content(content)

# glob validation & matching
class GlobError(Exception):
    pass

def validate_glob(pat):
    i=0; n=len(pat); brace_depth=0
    while i<n:
        c=pat[i]
        if c=='\\':
            if i+1>=n:
                raise GlobError(f"error parsing glob '{pat}': dangling '\\'")
            i+=2; continue
        if c=='[':
            j=i+1
            if j<n and pat[j] in '!^': j+=1
            # a ] immediately after [ or [! is literal
            if j<n and pat[j]==']': j+=1
            start_content=j
            found=False
            # content for range check: characters from i+1 (excluding !) to closing-1
            k=j
            while k<n:
                if pat[k]==']':
                    found=True; break
                k+=1
            if not found:
                raise GlobError(f"error parsing glob '{pat}': unclosed character class; missing ']'")
            content=pat[i+1:k]
            if content.startswith('!') or content.startswith('^'):
                content=content[1:]
            # parse ranges: use content chars; a leading ] is a char
            idx=0
            while idx < len(content):
                if idx+2 < len(content) and content[idx+1]=='-':
                    a=content[idx]; b=content[idx+2]
                    if ord(a)>ord(b):
                        raise GlobError(f"error parsing glob '{pat}': invalid range; '{a}' > '{b}'")
                    idx+=3
                else:
                    idx+=1
            i=k+1; continue
        if c=='{':
            brace_depth+=1; i+=1; continue
        if c=='}':
            if brace_depth>0: brace_depth-=1
            i+=1; continue
        i+=1
    if brace_depth>0:
        raise GlobError(f"error parsing glob '{pat}': unclosed alternate group; missing '}}' (maybe escape '{{' with '[{{]'?)")

def glob_to_regex(pat):
    # Translate glob (with **, *, ?, [], {a,b}) to regex matching whole string
    i=0; n=len(pat); out=[]
    while i<n:
        c=pat[i]
        if c=='*':
            if pat.startswith('**/',i):
                out.append('(?:.*/)?'); i+=3; continue
            if pat.startswith('/**',i) and i+3>=n:
                out.append('(?:/.*)?'); i+=3; continue
            if pat.startswith('**',i):
                out.append('.*'); i+=2; continue
            out.append('[^/]*'); i+=1; continue
        if c=='?':
            out.append('[^/]'); i+=1; continue
        if c=='[':
            j=i+1
            neg=False
            if j<n and pat[j] in '!^': neg=True; j+=1
            content_start=j
            if j<n and pat[j]==']': j+=1
            while j<n and pat[j]!=']': j+=1
            if j>=n:
                out.append(re.escape('[')); i+=1; continue
            content=pat[content_start:j]
            # escape for python regex class
            content=content.replace('\\','\\\\')
            if content.startswith(']'):
                content='\\]'+content[1:]
            out.append('['+('^' if neg else '')+content+']'); i=j+1; continue
        if c=='{':
            # find matching }
            depth=1; j=i+1; parts=[]; cur=[]
            while j<n and depth>0:
                if pat[j]=='\\' and j+1<n:
                    cur.append(pat[j:j+2]); j+=2; continue
                if pat[j]=='{': depth+=1; cur.append(pat[j])
                elif pat[j]=='}':
                    depth-=1
                    if depth>0: cur.append(pat[j])
                elif pat[j]==',' and depth==1:
                    parts.append(''.join(cur)); cur=[]
                else:
                    cur.append(pat[j])
                j+=1
            if depth!=0:
                out.append(re.escape(c)); i+=1; continue
            parts.append(''.join(cur))
            inner='|'.join(glob_to_regex_inner(p) for p in parts)
            out.append('(?:'+inner+')'); i=j; continue
        if c=='\\' and i+1<n:
            out.append(re.escape(pat[i+1])); i+=2; continue
        out.append(re.escape(c)); i+=1
    return ''.join(out)
def glob_to_regex_inner(pat):
    return glob_to_regex(pat)
def compile_glob(pat):
    return re.compile('^'+glob_to_regex(pat)+'$')
def match_ignore_pattern(pat, relpath, is_dir):
    # statix ignore / override semantics approximated
    if pat=='':
        return False
    p=pat
    dir_only=False
    if p.endswith('/'):
        dir_only=True; p=p.rstrip('/')
    if dir_only and not is_dir:
        # still if file is under a dir matched by ancestor logic in walk, caller checks ancestors
        pass
    if '/' not in p:
        base=relpath.split('/')[-1]
        return bool(compile_glob(p).match(base))
    else:
        pp=p[1:] if p.startswith('/') else p
        return bool(compile_glob(pp).match(relpath))

# gitignore
class GitignoreRule:
    __slots__=('pattern','neg','dir_only','anchored')
    def __init__(self,pattern,neg,dir_only,anchored):
        self.pattern=pattern; self.neg=neg; self.dir_only=dir_only; self.anchored=anchored

def parse_gitignore(content):
    rules=[]
    for raw in content.splitlines():
        line=raw
        if line.startswith('#'): continue
        # trailing spaces stripped unless escaped (simplified)
        line=line.rstrip(' ')
        if line.strip()=='': continue
        neg=False
        if line.startswith('!'):
            neg=True; line=line[1:]
        elif line.startswith('\\!'):
            line=line[1:]
        if line.startswith('\\#'):
            line=line[1:]
        dir_only=False
        if line.endswith('/'):
            dir_only=True; line=line.rstrip('/')
        anchored=False
        if '/' in line:
            anchored=True
            if line.startswith('/'): line=line[1:]
        try:
            validate_glob(line)
        except GlobError:
            continue
        rules.append(GitignoreRule(line,neg,dir_only,anchored))
    return rules

def gitignore_match(rules_with_dirs, relpath, is_dir):
    # rules_with_dirs: list of (base_rel_tuple, [rules]) from root to deep
    ignored=False
    rel_parts=relpath.split('/') if relpath else []
    for base,rules in rules_with_dirs:
        if len(rel_parts) <= len(base):
            continue
        if tuple(rel_parts[:len(base)]) != base:
            continue
        sub='/'.join(rel_parts[len(base):])
        for rule in rules:
            pat=rule.pattern
            matched=False
            if rule.anchored:
                matched=bool(compile_glob(pat).match(sub))
                if not matched and not rule.dir_only:
                    # also gitignore anchored pat can match leading dirs? e.g /foo matches foo/bar handled via ancestor check at dir level
                    pass
            else:
                matched=bool(compile_glob(pat).match(sub.split('/')[-1]))
            if matched:
                if rule.dir_only and not is_dir:
                    # if this is file, only counts if pattern matches an ancestor dir; caller evaluates file ancestors separately
                    continue
                ignored=not rule.neg
    return ignored

def path_extension_is_nix(path):
    name=os.path.basename(path)
    if name in ('.','..'): return False
    # Rust extension: last dot not at 0-with-only-dot
    if '.' not in name: return False
    if name.startswith('.') and name.count('.')==1: return False
    return name.rsplit('.',1)[-1]=='nix'

def collect_files(target, unrestricted, ignore_patterns):
    # validate patterns (CLI+config combined order controlled by caller)
    for pat in ignore_patterns:
        try:
            validate_glob(pat)
        except GlobError as e:
            raise SessionError(f"error parsing ignore list `{e}`")
    if not os.path.exists(target):
        raise SessionError(f"path error: file not found: {target}")
    files=[]
    messages=[]  # printed during load by caller in collected order
    def load_one(display):
        try:
            with open(display,'rb') as f: data=f.read()
            content=data.decode('utf-8')
        except Exception:
            messages.append(f"`{display}` contains non-utf8 content\n")
            return
        files.append((display,content))
    if not os.path.isdir(target):
        if path_extension_is_nix(target):
            load_one(target)
        return files,messages
    # walk directory recursively
    # stack: (displaydir, rel_tuple, gitignore_stack)
    git_stack=[]
    def read_gitignore(displaydir, rel_tuple):
        if unrestricted: return None
        gi=os.path.join(displaydir,'.gitignore') if displaydir not in ('','.') else '.gitignore' if displaydir=='.' else os.path.join(displaydir,'.gitignore')
        # simply use displaydir join
        try:
            path=os.path.join(displaydir,'.gitignore') if displaydir else '.gitignore'
            with open(path,'rb') as f: content=f.read().decode('utf-8','replace')
            return (rel_tuple, parse_gitignore(content))
        except Exception:
            return None
    # recursive function to preserve gitignore stack naturally
    def is_ignored(rel_tuple,is_dir,git_stack_local):
        relpath='/'.join(rel_tuple)
        # statix overrides first
        for pat in ignore_patterns:
            # directory ancestor matching: if pat matches this path
            if match_ignore_pattern(pat,relpath,is_dir):
                return True
        if unrestricted:
            return False
        # .git dir special
        if is_dir and rel_tuple and rel_tuple[-1]=='.git':
            return True
        if gitignore_match(git_stack_local,relpath,is_dir):
            return True
        # if any ancestor dir is gitignored (and no negation for file) handled by pruning; for files we already pruned dirs
        return False
    import sys as _sys
    _sys.setrecursionlimit(10000)
    def walk(displaydir, rel_tuple, git_stack_local, depth=0):
        if depth>500:
            return
        # load gitignore for this dir
        new_stack=list(git_stack_local)
        gi=read_gitignore(displaydir,rel_tuple)
        if gi is not None:
            new_stack.append(gi)
        try:
            entries=list(os.scandir(displaydir if displaydir else '.'))
        except OSError:
            return
        # sorted for determinism (reference is nondeterministic in parallel)
        entries.sort(key=lambda e:e.name)
        for entry in entries:
            name=entry.name
            child_rel=rel_tuple+(name,)
            display=os.path.join(displaydir,name) if displaydir else name
            try:
                is_dir=entry.is_dir(follow_symlinks=True)
                is_file=entry.is_file(follow_symlinks=True)
            except OSError:
                continue
            if is_dir:
                if is_ignored(child_rel,True,new_stack):
                    continue
                # if gitignored as dir via ancestor dir_only patterns etc already in is_ignored(gitignore_match)
                walk(display,child_rel,new_stack,depth+1)
            elif is_file:
                if is_ignored(child_rel,False,new_stack):
                    continue
                # check if any ancestor component matches ignore pattern (pruned already for dirs mostly)
                if not path_extension_is_nix(name):
                    continue
                load_one(display)
            else:
                continue
    walk(target,(),[])
    return files,messages

def read_stdin_source(panic_loc):
    data=sys.stdin.buffer.read()
    # Rust BufRead::lines
    if data==b'':
        lines=[]
    else:
        parts=data.split(b'\n')
        if data.endswith(b'\n'):
            parts=parts[:-1]
        lines=[]
        for part in parts:
            # strip trailing \r if the line ended with \n in original (all except perhaps final non-terminated)
            # Determine if this part was terminated: all parts except last when not ending with \n, or all when ending.
            lines.append(part)
        # Now strip \r for terminated lines
        out=[]
        ended_with_nl=data.endswith(b'\n')
        for idx,part in enumerate(lines):
            terminated = ended_with_nl or idx < len(lines)-1
            if terminated and part.endswith(b'\r'):
                part=part[:-1]
            try:
                out.append(part.decode('utf-8'))
            except UnicodeDecodeError:
                panic_exit(panic_loc,'called `Result::unwrap()` on an `Err` value: Error { kind: InvalidData, message: "stream did not contain valid UTF-8" }')
        lines=out
    return "\n".join(lines)

def create_check_session(conf_path,target,cli_ignore,unrestricted,use_stdin,mode='check'):
    config=load_config(conf_path)
    if use_stdin:
        loc={'check':'bin/src/config.rs:74:28','fix':'bin/src/config.rs:127:28','single':'bin/src/config.rs:183:28'}[mode]
        source=read_stdin_source(loc)
        return config, [('<stdin>',source)], []
    combined=list(cli_ignore or [])+list(config.get('ignore') or [])
    files,messages=collect_files(target,unrestricted,combined)
    return config, files, messages
