class SessionError(Exception): pass
class FixerError(Exception): pass

def format_os_error(e):
    if getattr(e,'errno',None) is not None:
        msg=e.strerror or str(e)
        return f"{msg} (os error {e.errno})"
    return str(e)

def panic_exit(location,msg):
    try: sys.stdout.flush()
    except Exception: pass
    pid=os.getpid()
    sys.stderr.write(f"\nthread 'main' ({pid}) panicked at {location}:\n{msg}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    sys.stderr.flush()
    raise SystemExit(101)

