# ---------- ariadne-like renderer ----------
ESC='\x1b'
def col_wrap(text,code):
    return f"{ESC}[{code}m{text}{ESC}[0m"
def col_each(text,code):
    return ''.join(col_wrap(ch,code) for ch in text)
def char_width(ch, disp_col):
    if ch=='\t':
        return 4 - (disp_col % 4)
    import unicodedata
    if unicodedata.combining(ch):
        return 0
    if unicodedata.east_asian_width(ch) in ('W','F'):
        return 2
    if ord(ch)<32:
        return 0
    return 1

class RenderSource:
    def __init__(self,src):
        self.src=src
        self.chars=list(src)
        self.lines=[]  # (start_char_idx, text_without_newline)
        start=0
        for part in src.split('\n'):
            # split always gives at least one; if src ends with \n last part '' represents phantom line
            self.lines.append((start,part))
            start += len(part)+1
        if src=="":
            self.lines=[]
    def pos_to_line_col(self,pos):
        # pos is byte offset interpreted as char offset
        if not self.lines:
            return (0,0)
        # find line whose interval [start, start+len] includes pos
        for idx,(st,txt) in enumerate(self.lines):
            if st <= pos <= st+len(txt):
                return idx, pos-st
            if pos < st:
                # pos is on previous newline? previous handled by <= start+len; fallback
                return max(idx-1,0), pos-(self.lines[idx-1][0] if idx>0 else 0)
        # beyond
        idx=len(self.lines)-1; st,txt=self.lines[idx]
        return idx, pos-st
    def disp_col(self,line_idx,char_col):
        if line_idx<0 or line_idx>=len(self.lines): return char_col
        txt=self.lines[line_idx][1]
        col=0
        for ch in txt[:max(0,char_col)]:
            col += char_width(ch,col)
        if char_col>len(txt):
            col += (char_col-len(txt))
        return col
    def line_disp_len(self,line_idx):
        if line_idx<0 or line_idx>=len(self.lines): return 0
        txt=self.lines[line_idx][1]
        col=0
        for ch in txt: col += char_width(ch,col)
        return col

def format_label_note(note):
    # split on backticks; odd segments cyan
    parts=note.split('`')
    out=[]
    for i,p in enumerate(parts):
        if i%2==1:
            out.append(col_wrap(p,'36'))
        else:
            out.append(p)
    return ''.join(out)

