class ClapExit(Exception):
    def __init__(self,text,code=2,to_stderr=True):
        self.text=text; self.code=code; self.to_stderr=to_stderr

def jaro(s1,s2):
    if s1==s2: return 1.0
    len1,len2=len(s1),len(s2)
    if len1==0 or len2==0: return 0.0
    match_distance=max(len1,len2)//2-1
    if match_distance<0: match_distance=0
    s1_matches=[False]*len1; s2_matches=[False]*len2
    matches=0
    for i in range(len1):
        start=max(0,i-match_distance); end=min(i+match_distance+1,len2)
        for j in range(start,end):
            if not s2_matches[j] and s1[i]==s2[j]:
                s1_matches[i]=True; s2_matches[j]=True; matches+=1; break
    if matches==0: return 0.0
    k=0; transpositions=0
    for i in range(len1):
        if s1_matches[i]:
            while not s2_matches[k]: k+=1
            if s1[i]!=s2[k]: transpositions+=1
            k+=1
    transpositions//=2
    return (matches/len1 + matches/len2 + (matches-transpositions)/matches)/3
def jaro_winkler(s1,s2):
    j=jaro(s1,s2)
    if j>0.7:
        prefix=0
        for i in range(min(len(s1),len(s2),4)):
            if s1[i]==s2[i]: prefix+=1
            else: break
        j += prefix*0.1*(1-j)
    return j
def did_you_mean(value,candidates):
    best=None; best_score=0.0
    for cand in candidates:
        score=jaro_winkler(value,cand)
        if score>best_score:
            best_score=score; best=cand
    if best is not None and best_score>0.8:
        return best
    return None

